arguments.command:
curl -s "https://www.googleapis.com/calendar/v3/calendars/c_e70cd8ef76a09a485b101f11f1@group.calendar.google.com/acl?maxResults=250" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if 'error' in d:
    print('ERROR:', d['error'].get('code'), d['error'].get('message'))
else:
    for it in d.get('items',[]):
        print(it.get('id'),'|',it.get('role'),'|',it.get('scope',{}).get('type'),'|',it.get('scope',{}).get('value'))
    print('---nextPageToken:', d.get('nextPageToken'))
"

